async function allowed(request,env){const value=request.headers.get('cookie')?.match(/(?:^|;\\s*)portfolio_session=([^;]+)/)?.[1];if(!value)return false;const [payload,sig]=value.split('.');if(!payload||!sig)return false;const expected=await sign(payload,env.SESSION_SECRET);if(sig.length!==expected.length)return false;let diff=0;for(let i=0;i<sig.length;i++)diff|=sig.charCodeAt(i)^expected.charCodeAt(i);if(diff)return false;try{return JSON.parse(new TextDecoder().decode(unb64(payload))).exp>Date.now()}catch{return false}}
const cookie=token=>`portfolio_session=${token}; Path=/; Max-Age=2592000; HttpOnly; Secure; SameSite=None`,clear='portfolio_session=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=None';
function db(env,path,options={}){return fetch(`${env.SUPABASE_URL}${path}`,{...options,headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,'content-type':'application/json',...options.headers}})}async function body(request){try{if((request.headers.get('content-type')||'').includes('application/x-www-form-urlencoded'))return Object.fromEntries(new URLSearchParams(await request.text()));return await request.json()}catch{return null}}
function valid(row){return row&&['BUY','SELL','DEPOSIT','WITHDRAW'].includes(row.trade_type)&&typeof row.ticker==='string'&&typeof row.traded_at==='string'&&row.ticker.length<=15&&String(row.memo||'').length<=500&&[row.quantity,row.price,row.amount,row.fee].every(v=>Number.isFinite(Number(v))&&Number(v)>=0)}
async function api(request,env,url){
  if(url.pathname==='/api/session'){if(request.method==='GET')return json({authenticated:await allowed(request,env)});if(request.method==='DELETE')return json({ok:true},200,{'set-cookie':clear});if(request.method!=='POST')return json({error:'허용되지 않은 요청입니다.'},405);const input=await body(request),given=enc.encode(input?.password||''),expected=enc.encode(env.DASHBOARD_PASSWORD);let diff=given.length^expected.length;for(let i=0;i<Math.max(given.length,expected.length);i++)diff|=(given[i]||0)^(expected[i]||0);if(diff)return json({error:'비밀번호가 올바르지 않습니다.'},401);const headers={'set-cookie':cookie(await session(env))};return (request.headers.get('accept')||'').includes('text/html')?new Response(null,{status:303,headers:{...headers,location:'/'}}):json({ok:true},200,headers)}
  if(!await allowed(request,env))return json({error:'접근 권한이 없습니다.'},401);
  if(url.pathname==='/api/data'&&request.method==='GET'){const [transactions,snapshots]=await Promise.all([db(env,`/rest/v1/transactions?select=*&user_id=eq.${env.PORTFOLIO_USER_ID}&order=traded_at.desc`),db(env,`/rest/v1/daily_snapshots?select=snapshot_date,total_equity,total_cost,cash_balance,holdings&user_id=eq.${env.PORTFOLIO_USER_ID}&order=snapshot_date.asc`)]);if(!transactions.ok||!snapshots.ok)return json({error:'데이터를 읽지 못했습니다.'},502);return json({transactions:await transactions.json(),snapshots:await snapshots.json()})}
  if(url.pathname==='/api/quotes'&&request.method==='POST'){const input=await body(request),tickers=[...new Set(Array.isArray(input?.tickers)?input.tickers.filter(t=>typeof t==='string'&&/^[A-Z.]{1,15}$/i.test(t)).map(t=>t.toUpperCase()):[])];if(!tickers.length)return json({quotes:[],fetchedAt:new Date().toISOString()});const response=await db(env,'/functions/v1/market-quotes',{method:'POST',body:JSON.stringify({tickers})});if(!response.ok)return json({error:'시세를 불러오지 못했습니다.'},502);return new Response(await response.text(),{headers:{'content-type':'application/json','cache-control':'no-store'}})}
  if(url.pathname==='/api/transactions'&&request.method==='POST'){const input=await body(request);if(!valid(input))return json({error:'거래 입력값을 확인하세요.'},400);const response=await db(env,'/rest/v1/transactions',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({...input,user_id:env.PORTFOLIO_USER_ID,ticker:input.ticker.toUpperCase(),memo:String(input.memo||'')})});if(!response.ok)return json({error:'거래를 저장하지 못했습니다.'},502);return new Response(await response.text(),{status:201,headers:{'content-type':'application/json'}})}
  const match=url.pathname.match(/^\/api\/transactions\/([0-9a-f-]{36})$/i);if(match&&request.method==='DELETE'){const response=await db(env,`/rest/v1/transactions?id=eq.${match[1]}&user_id=eq.${env.PORTFOLIO_USER_ID}`,{method:'DELETE'});return response.ok?new Response(null,{status:204}):json({error:'거래를 삭제하지 못했습니다.'},502)}return json({error:'찾을 수 없는 요청입니다.'},404)
}
import { staticAsset } from './assets.js';
export default {fetch(request,env){const url=new URL(request.url);if(url.pathname==='/__health')return new Response('ok',{headers:{'content-type':'text/plain','cache-control':'no-store'}});if(url.pathname.startsWith('/api/'))return api(request,env,url);return staticAsset(url.pathname)||new Response('찾을 수 없습니다.',{status:404})}};
